import { test, expect } from '@playwright/test';

test.describe('API Error Banner Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display error banner when API call fails', async ({ page }) => {
    // Setup intercept for failed API call
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Verify error banner is not visible initially
    const errorBanner = page.getByRole('region', { name: /error/i });
    await expect(errorBanner).not.toBeVisible();

    // Verify error message is not visible initially
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();

    // Trigger API call
    const dataButton = page.getByRole('button', { name: /load data/i });
    await dataButton.click();

    // Wait for error banner to appear
    await page.waitForTimeout(500);

    // Verify error banner is visible
    await expect(errorBanner).toBeVisible();

    // Verify error message is visible
    await expect(errorMessage).toBeVisible();

    // Verify error message contains specific error details
    await expect(errorMessage).toContainText('Failed to load data');

    // Verify error banner has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button works
    await closeButton.click();

    // Verify error banner is hidden after close
    await expect(errorBanner).not.toBeVisible();
  });

  test('should clear error banner when API call succeeds', async ({ page }) => {
    // Setup successful API call
    await page.route('**/api/data', (route) => {
      route.continue();
    });

    // Verify error banner is not visible initially
    const errorBanner = page.getByRole('region', { name: /error/i });
    await expect(errorBanner).not.toBeVisible();

    // Verify error message is not visible initially
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();

    // Trigger API call
    const dataButton = page.getByRole('button', { name: /load data/i });
    await dataButton.click();

    // Wait for error banner to appear
    await page.waitForTimeout(500);

    // Verify error banner is visible
    await expect(errorBanner).toBeVisible();

    // Verify error message is visible
    await expect(errorMessage).toBeVisible();

    // Verify error message contains specific error details
    await expect(errorMessage).toContainText('Failed to load data');

    // Verify error banner has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button works
    await closeButton.click();

    // Verify error banner is hidden after close
    await expect(errorBanner).not.toBeVisible();

    // Verify error message is gone
    await expect(errorMessage).not.toBeVisible();

    // Verify API call was successful
    const successMessage = page.getByText(/success/i);
    await expect(successMessage).toBeVisible();

    // Verify success message contains expected data
    await expect(successMessage).toContainText('Data loaded successfully');
  });
});
